const add = function(num1, num2) {
	return num1 + num2;
};

const subtract = function(num1, num2) {
	return num1 - num2;
};

const sum = function(arr) {
	arr.reduce((total, num) => total + num);
};

const multiply = function(arr) {
  arr.reduce((total, num) => total * num);
};

